Determine the current year at runtime, select only that year's electricity bills, deduplicate monthly PDF/text variants by preferring text when available, and read every selected bill so the amounts can be extracted next.

```python
from datetime import datetime
from pathlib import PurePosixPath

current_year = datetime.now().year
electricity_files = [
    path for path in bill_files
    if '/bills/electricity/' in path and PurePosixPath(path).stem.startswith(f'{current_year}-')
]

files_by_month = {}
for path in electricity_files:
    month = PurePosixPath(path).stem
    if month not in files_by_month or (path.endswith('.txt') and not files_by_month[month].endswith('.txt')):
        files_by_month[month] = path

selected_electricity_files = [files_by_month[month] for month in sorted(files_by_month)]
electricity_bill_records = [
    apis.file_system.show_file(file_path=path, access_token=file_system_access_token)
    for path in selected_electricity_files
]
for record in electricity_bill_records:
    print(record['path'])
    print(record['content'])
```

